PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY, mobile TEXT UNIQUE NOT NULL, name TEXT DEFAULT '', business TEXT DEFAULT '', city TEXT DEFAULT '', address TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, customer_id TEXT, state TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(sku TEXT PRIMARY KEY, data TEXT NOT NULL, active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS prices(sku TEXT PRIMARY KEY REFERENCES products(sku), amount INTEGER NOT NULL CHECK(amount>=0), version INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory(sku TEXT PRIMARY KEY REFERENCES products(sku), quantity INTEGER NOT NULL CHECK(quantity>=0), version INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS carts(session_id TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 0, items TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY, session_id TEXT NOT NULL, revision INTEGER NOT NULL, snapshot TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, request_key TEXT UNIQUE NOT NULL, quote_id TEXT UNIQUE NOT NULL, snapshot TEXT NOT NULL, created TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY, session_id TEXT, kind TEXT, data TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations(id INTEGER PRIMARY KEY, session_id TEXT, turn_id TEXT, role TEXT, text TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id,turn_id,role));
CREATE TABLE IF NOT EXISTS consents(id INTEGER PRIMARY KEY, session_id TEXT, kind TEXT, accepted INTEGER, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS callbacks(id TEXT PRIMARY KEY, customer_id TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT 'در انتظار تماس');
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS promotions(id TEXT PRIMARY KEY, data TEXT NOT NULL);
